package io.knowledgebrain.collaboration;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class GroupApiTest {
 GroupStore store;GroupSpaceClient space;GroupController api;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID owner=ids.next(),group=ids.next(),spaceId=ids.next();String token="b".repeat(43),parent="00-"+"a".repeat(32)+"-"+"c".repeat(16)+"-01";
 @BeforeEach void setup(){store=mock(GroupStore.class);space=mock(GroupSpaceClient.class);api=new GroupController(store,space,"https://localhost:8443");when(space.access(eq(token),anyList(),eq(parent))).thenReturn(new GroupSpaceClient.Access(owner,"REGISTERED",List.of()));}
 MockHttpServletRequest req(String method,String body){var r=new MockHttpServletRequest(method,"/api/groups");r.setSecure(true);r.addHeader("Cookie","__Host-brain_guest="+token);r.addHeader("Origin","https://localhost:8443");r.addHeader("traceparent",parent);r.addHeader("Idempotency-Key","d".repeat(32));r.setContentType("application/json");r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 GroupStore.Group row(String state){return new GroupStore.Group(group,owner,"x","",state,state.equals("ACTIVE")?spaceId:null,state.equals("ACTIVE")?2:1,Instant.now(),Instant.now(),"PRIVATE");}
 @Test void failedSpaceProvisionRetainsRequestAndRetryFinishes()throws Exception{var pending=row("PENDING");var active=row("ACTIVE");when(store.request(owner,"d".repeat(32),"x","","a".repeat(32))).thenReturn(pending);when(space.provision(token,group,parent)).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE)).thenReturn(new GroupSpaceClient.Access(owner,"REGISTERED",List.of(new GroupSpaceClient.Grant(group,spaceId,"OWNER","PRIVATE"))));when(store.activate(group,owner,spaceId,"a".repeat(32))).thenReturn(active);assertThrows(ResponseStatusException.class,()->api.create(req("POST","{\"title\":\"x\",\"description\":\"\"}")));verify(store,never()).activate(any(),any(),any(),any());assertEquals(active,api.create(req("POST","{\"title\":\"x\",\"description\":\"\"}")).getBody());}
 @Test void foreignCreatorAndRevokedSpaceAreHidden()throws Exception{when(store.owned(group,owner)).thenReturn(row("ACTIVE"));assertThrows(ResponseStatusException.class,()->api.detail(group.toString(),req("GET","")));verify(space).access(token,List.of(group),parent);}
 @Test void activeAccessMustMatchExactSpace()throws Exception{when(store.owned(group,owner)).thenReturn(row("ACTIVE"));when(space.access(token,List.of(group),parent)).thenReturn(new GroupSpaceClient.Access(owner,"REGISTERED",List.of(new GroupSpaceClient.Grant(group,ids.next(),"OWNER","PRIVATE"))));assertThrows(ResponseStatusException.class,()->api.detail(group.toString(),req("GET","")));}
 @Test void emptyFilteredPageStillAdvancesCandidateCursor()throws Exception{var g=row("ACTIVE");var next=new GroupStore.Group(ids.next(),owner,"other","","PENDING",null,1,Instant.now(),Instant.now(),"PRIVATE");when(store.candidates(owner,null,1)).thenReturn(List.of(g,next));var r=req("GET","");r.addParameter("limit","1");var page=api.list(r).getBody();assertTrue(page.items().isEmpty());assertEquals(group,page.nextAfter());}
 @Test void duplicateCookiesInsecureAndCrossOriginNeverReachServices(){for(int mode=0;mode<3;mode++){var r=req("POST","{}");if(mode==0)r.setSecure(false);if(mode==1)r.addHeader("Cookie","__Host-brain_guest="+token);if(mode==2)r.addHeader("Origin","https://elsewhere.example");assertThrows(ResponseStatusException.class,()->api.create(r));}verifyNoInteractions(store,space);}
 @Test void rejectsBodyQueriesUnknownFieldsAndAmbiguousJson(){for(String body:List.of("{\"title\":\"x\",\"description\":\"\",\"ownerId\":\"forged\"}","{\"title\":\"x\",\"title\":\"y\",\"description\":\"\"}","{\"title\":\"x\",\"description\":\"\"} {}","{\"title\":\"\",\"description\":\"\"}"))assertThrows(ResponseStatusException.class,()->api.create(req("POST",body)));var read=req("GET","{}");assertThrows(ResponseStatusException.class,()->api.list(read));var query=req("GET","");query.addParameter("actorId","forged");assertThrows(ResponseStatusException.class,()->api.list(query));verifyNoInteractions(store,space);}
 @Test void retiredOrGuestAuthorizationFailureCreatesNothing(){when(space.access(eq(token),anyList(),eq(parent))).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN));assertThrows(ResponseStatusException.class,()->api.create(req("POST","{\"title\":\"x\",\"description\":\"\"}")));verifyNoInteractions(store);}
 @Test void strictUnicodeAndUtf8BoundsPreserveLiteralText(){assertEquals("<script>",GroupInput.settings("{\"title\":\"<script>\",\"description\":\"line\\n둘\"}".getBytes(java.nio.charset.StandardCharsets.UTF_8)).title());assertFalse(GroupInput.unicode("x\u0000"));assertFalse(GroupInput.unicode("x\ud800"));assertThrows(ResponseStatusException.class,()->GroupInput.id(UUID.randomUUID().toString()));}
}
